use std::{future, sync::{Arc, Mutex}, time::Duration};
use tokio::{runtime::Builder, time};
use tokio_util::time::DelayQueue;

fn main() {
    Builder::new_current_thread().enable_all().build().unwrap().block_on(async {
        let mut queue = DelayQueue::new();
        let key = queue.insert("foo", Duration::from_secs(100));
        let queue1 = Arc::new(Mutex::new(queue));
        let queue2 = queue1.clone();
        let mut waiter = tokio::spawn(async move {
            future::poll_fn(|cx| queue1.lock().unwrap().poll_expired(cx)).await
        });
        let remover = tokio::spawn(async move {
            time::sleep(Duration::from_millis(100)).await;
            queue2.lock().unwrap().remove(&key);
        });
        let result = time::timeout(Duration::from_millis(500), &mut waiter).await;
        remover.await.expect("remover panicked");
        if result.is_err() {
            waiter.abort();
            panic!("last-item removal did not wake poll_expired: task timed out");
        }
        assert!(result.unwrap().expect("waiter panicked").is_none());
    });
}
